from abc import abstractmethod
from ..section_generic import SectionGeneric


class YAMLBasedSectionGeneric(SectionGeneric):

    @abstractmethod
    def __init__(self, section_name):
        self.section_name = section_name

    def generate_section_content(self, *args, **kwargs):
        section_content = self._prepare_section_content(*args, **kwargs)
        return {self.section_name: section_content}
